#!/usr/bin/env python3
"""Emit hps/lib/h264ring_cavlc_tab.h -- the tables of the CAVLC -> CABAC rewriter (fj#20,
hps/lib/h264ring_cavlc.c, docs/cavlc.md) -- from the project's spec transcriptions:
tools/cabac_tables.py (context initialisation, rangeTabLPS, the state transitions),
tools/high_tables.py (the 8x8 significance / last context maps) and tools/cavlc_tables.py
(coeff_token, total_zeros, run_before, the coded_block_pattern mapping). Never edit the
header by hand; `--check` fails when it differs from what this script would write.

    gen_hps_tables.py [-o hps/lib/h264ring_cavlc_tab.h] [--check]
"""
import argparse
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import cabac_tables as CT  # noqa: E402
import cavlc_tables as VT  # noqa: E402
import high_tables as HT   # noqa: E402

OUT = os.path.join(HERE, "..", "hps", "lib", "h264ring_cavlc_tab.h")


def arr(w, ctype, name, dims, flat, per_line=16):
    """A flat array (C's -Wmissing-braces): index [i][j] as [i * dims[1] + j]."""
    n = 1
    for d in dims:
        n *= d
    if len(flat) != n:
        raise SystemExit("gen_hps_tables: %s has %d values, expected %d" % (name, len(flat), n))
    w.append("static const %s %s[%d] = {   /* %s */" % (ctype, name, n, "".join("[%d]" % d for d in dims)))
    for i in range(0, len(flat), per_line):
        w.append("    " + ", ".join(str(v) for v in flat[i:i + per_line]) + ",")
    w.append("};")
    w.append("")


def vlc_rows(w, name, rows, note):
    """A VLC table as {len, code, value} triples, one array per row, terminated by len 0."""
    w.append("/* %s */" % note)
    for k, row in rows:
        items = ["{%d, 0x%x, %d}" % (len(c), int(c, 2), v) for c, v in row] + ["{0, 0, 0}"]
        w.append("static const struct cv_code %s_%s[] = {" % (name, k))
        for i in range(0, len(items), 6):
            w.append("    " + ", ".join(items[i:i + 6]) + ",")
        w.append("};")
    w.append("")


def render():
    w = ["/* GENERATED by tools/gen_hps_tables.py from tools/cabac_tables.py, tools/high_tables.py and",
         " * tools/cavlc_tables.py (each transcribed from T-REC-H.264-202606.pdf and cross-checked",
         " * against ffmpeg) -- never edit by hand. The CAVLC -> CABAC rewriter's tables (fj#20). */",
         "#ifndef H264RING_CAVLC_TAB_H",
         "#define H264RING_CAVLC_TAB_H",
         "",
         "#include <stdint.h>",
         "",
         "#define CV_NUM_CTX %d" % CT.NUM_CTX,
         "",
         "/* 9.3.1.1: (m, n) per ctxIdx for the init sets I, cabac_init_idc 0, 1, 2; (0, 0) where the",
         " * spec says 'na' (the model's and the fabric's convention) */"]
    flat = []
    for s in ("I", 0, 1, 2):
        for v in CT.CTX_INIT[s]:
            flat += list(v) if v is not None else [0, 0]
    arr(w, "int8_t", "cv_ctx_init", [4, CT.NUM_CTX, 2], flat)
    w.append("/* Table 9-44 rangeTabLPS[pStateIdx][qCodIRangeIdx], Table 9-45 transitions */")
    arr(w, "uint8_t", "cv_range_lps", [64, 4], [v for r in CT.RANGE_LPS for v in r])
    arr(w, "uint8_t", "cv_trans_lps", [64], CT.TRANS_IDX_LPS)
    arr(w, "uint8_t", "cv_trans_mps", [64], CT.TRANS_IDX_MPS)
    w.append("/* 9.3.3.2.1.1 on a state byte s = pStateIdx << 1 | valMPS: cv_trans[s << 1 | binVal] = the next s */")
    tr = []
    for st in range(128):
        p, mps = st >> 1, st & 1
        for b in (0, 1):
            if b == mps:
                tr.append(CT.TRANS_IDX_MPS[p] << 1 | mps)
            else:
                tr.append(CT.TRANS_IDX_LPS[p] << 1 | (1 - mps if p == 0 else mps))
    arr(w, "uint8_t", "cv_trans", [256], tr)
    w.append("/* Table 9-43: ctxIdxInc of significant_coeff_flag (frame / field) and")
    w.append(" * last_significant_coeff_flag for ctxBlockCat 5, by levelListIdx 0..62 */")
    arr(w, "uint8_t", "cv_sig8_frame", [63], HT.SIG8_FRAME)
    arr(w, "uint8_t", "cv_sig8_field", [63], HT.SIG8_FIELD)
    arr(w, "uint8_t", "cv_last8", [63], HT.LAST8)
    w.append("/* Table 9-4 (a): coded_block_pattern by codeNum (ChromaArrayType 1 or 2) */")
    arr(w, "uint8_t", "cv_cbp_intra", [48], VT.CBP_INTRA)
    arr(w, "uint8_t", "cv_cbp_inter", [48], VT.CBP_INTER)
    w.append("struct cv_code { uint8_t len; uint16_t code; uint8_t value; };")
    w.append("")
    rows = []
    for col in range(6):
        rows.append((col, [(c, (tc << 2) | t1) for (t1, tc), c in sorted(VT.COEFF_TOKEN[col].items(),
                                                                         key=lambda kv: (kv[0][1], kv[0][0]))]))
    vlc_rows(w, "cv_coeff_token", rows,
             "Table 9-5: value = TotalCoeff << 2 | TrailingOnes; rows 0..5 = 0<=nC<2, 2<=nC<4, 4<=nC<8, 8<=nC, "
             "nC -1, nC -2")
    vlc_rows(w, "cv_total_zeros", [(k, [(c, z) for z, c in enumerate(VT.TOTAL_ZEROS[k])]) for k in range(1, 16)],
             "Tables 9-7 / 9-8: total_zeros by tzVlcIndex 1..15 (4x4 blocks)")
    vlc_rows(w, "cv_total_zeros_cdc", [(k, [(c, z) for z, c in enumerate(VT.TOTAL_ZEROS_CDC[k])])
                                       for k in range(1, 4)],
             "Table 9-9 (a): total_zeros by tzVlcIndex 1..3 (chroma DC 2x2)")
    vlc_rows(w, "cv_run_before", [(k, [(c, r) for r, c in enumerate(VT.RUN_BEFORE[k])]) for k in range(1, 8)],
             "Table 9-10: run_before by zerosLeft 1..6, 7 = '> 6'")
    w.append("static const struct cv_code *const cv_coeff_token_rows[6] = {")
    w.append("    " + ", ".join("cv_coeff_token_%d" % k for k in range(6)) + ",")
    w.append("};")
    w.append("static const struct cv_code *const cv_total_zeros_rows[15] = {")
    w.append("    " + ", ".join("cv_total_zeros_%d" % k for k in range(1, 16)) + ",")
    w.append("};")
    w.append("static const struct cv_code *const cv_total_zeros_cdc_rows[3] = {")
    w.append("    " + ", ".join("cv_total_zeros_cdc_%d" % k for k in range(1, 4)) + ",")
    w.append("};")
    w.append("static const struct cv_code *const cv_run_before_rows[7] = {")
    w.append("    " + ", ".join("cv_run_before_%d" % k for k in range(1, 8)) + ",")
    w.append("};")
    w.append("")
    w.append("#endif")
    w.append("")
    return "\n".join(w)


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("-o", "--out", default=OUT)
    ap.add_argument("--check", action="store_true", help="compare with the existing header, write nothing")
    a = ap.parse_args(argv)
    text = render()
    if a.check:
        same = os.path.exists(a.out) and open(a.out).read() == text
        print("%s %s the generator" % (os.path.relpath(a.out), "matches" if same else "DIFFERS FROM"))
        return 0 if same else 1
    open(a.out, "w").write(text)
    print("wrote %s" % os.path.relpath(a.out))
    return 0


if __name__ == "__main__":
    sys.exit(main())
